function marketTrustState(freshness,observedAt,fetchedAt){const f=String(freshness||'UNKNOWN').trim().toUpperCase(),o=Date.parse(observedAt),g=Date.parse(fetchedAt),n=Date.now();if(!Number.isFinite(o)||!Number.isFinite(g))return {state:'INVALID_PROVENANCE',observation_lag_seconds:null,response_age_seconds:null};const observationLag=Math.max(0,Math.round((g-o)/1000)),responseAge=Math.max(0,Math.round((n-g)/1000));if(o>n+60000||g>n+60000)return {state:'CLOCK_SKEW',observation_lag_seconds:observationLag,response_age_seconds:responseAge};if(f.includes('STALE')||responseAge>900)return {state:'SOURCE_STALE',observation_lag_seconds:observationLag,response_age_seconds:responseAge};if(f.includes('DELAY')||observationLag>900)return {state:'SOURCE_DELAYED',observation_lag_seconds:observationLag,response_age_seconds:responseAge};if(['FRESH','REALTIME','REAL_TIME','CURRENT'].includes(f))return {state:'SOURCE_FRESH',observation_lag_seconds:observationLag,response_age_seconds:responseAge};return {state:'SOURCE_UNCLASSIFIED',observation_lag_seconds:observationLag,response_age_seconds:responseAge}}
function marketRouteState(v){if(v==null)return null;if(typeof v!=='object'||Array.isArray(v))return false;const role=String(v.role||'').toUpperCase(),state=String(v.state||'').toUpperCase().slice(0,48),provider=v.provider==null?null:String(v.provider).trim().slice(0,64),health=v.health==null?null:String(v.health).toUpperCase().slice(0,24),http=v.http_status==null?null:Number(v.http_status);if(!['PRIMARY','FALLBACK'].includes(role)||!/^[A-Z0-9_:-]{2,48}$/.test(state)||provider!==null&&provider.length<2||health!==null&&!/^[A-Z0-9_:-]{2,24}$/.test(health)||http!==null&&(!Number.isInteger(http)||http<100||http>599))return false;return {role,state,provider,health,http_status:http}}
